/* FitFirst V2 (forked from V1, restyled by the Atelier system) — the floor: live queue, visit detail, visit history, staff-app sale (POS level L0) */
(function () {
  const FF = window.FF, U = FF.ui, esc = FF.esc, $ = FF.$, R = FF.ROLES;
  const V = (code) => FF.db.visits.find((v) => v.code === code);
  const ev = (v, type, text) => { v.events = v.events || []; v.events.push({ at: Date.now(), type, text, by: (FF.me() || {}).name }); };
  const sumry = (p) => p ? [FF.TAX.depts[p.dept], (p.cats || []).map(FF.catName).join(', '), p.occasion ? FF.cap(p.occasion) : '', p.budget ? 'up to ' + FF.inr(p.budget) : ''].filter(Boolean).join(' · ') : 'Details erased';

  /* ---------- queue ---------- */
  /* the V1 queue page is replaced by V2's Sessions page (console-sessions.js) */
  FF.act('q-find', (f) => { let c = f.code.toUpperCase().replace(/^FF-?/, ''); c = 'FF-' + c; if (!V(c)) return FF.toast('No visit with code ' + c, 'bad'); FF.go('#/session/' + c); });
  FF.act('v-claim', (d) => { const v = V(d.code), me = FF.me(); if (v.status !== 'WAITING') { FF.toast('Already claimed by ' + FF.staffName(v.staff), 'warn'); return FF.render(); } v.status = 'ASSIGNED'; v.staff = me.id; ev(v, 'assigned', 'Claimed by ' + me.name); FF.save(); FF.go('#/session/' + v.code); FF.toast('Assigned to you', 'ok'); });

  /* ---------- visit detail ---------- */
  const VS = { tab: 0 };
  FF.page('session', { title: 'Session', parent: 'queue', icon: 'users', roles: R.FLOOR, render: (code) => {
    const v = V(code), me = FF.me(); if (!v) return U.empty('search', 'No visit with that code', 'Codes expire and are removed after the retention period.', `<a class="btn" href="#/sessions">Back to sessions</a>`);
    if (v.erased) return `<div class="ph1"><div><a class="link small" href="#/sessions">← Live queue</a><h1 class="code mt8">${v.code}</h1></div></div>` + U.empty('shield', 'This shopper asked for their data to be deleted', 'Erased on ' + FF.fmtDT(v.erasedAt) + '. Any bill is kept in the sales register because GST law requires it.');
    const pr = v.profiles[VS.tab] || v.profiles[0] || {}, open = ['WAITING', 'ASSIGNED', 'TRYING', 'BROWSING'].includes(v.status), picks = v.picks.filter((p) => (p.profile || 0) === (v.profiles[VS.tab] ? VS.tab : 0)).sort((a, b) => (v.shortlist.includes(b.pid) - v.shortlist.includes(a.pid)) || a.rank - b.rank);
    const sale = v.sale && FF.db.sales.find((s) => s.id === v.sale), inBag = v.picks.filter((p) => p.state === 'bag');
    const pick = (pk) => { const p = FF.prod(pk.pid); if (!p) return ''; const sz = pk.size, q = sz ? p.stock[sz] || 0 : FF.stockTotal(p), out = q <= 0 && pk.state !== 'bought', band = FF.ageBand(p), push = FF.db.pushes.find((x) => x.pid === p.id && x.active);
      const stt = { shown: '', shortlisted: U.badge('Shopper wants to try', 'brass'), tried: U.badge('Tried', 'info'), rejected: U.badge('Rejected' + (pk.reason ? ' · ' + pk.reason : ''), ''), bag: U.badge('In the bill', 'ok'), bought: U.badge('Bought', 'ok'), added: U.badge('Added by staff', 'info') }[pk.state] || '';
      return `<div class="pk"><div class="gimg">${FF.garment(p)}</div><div class="col gap6"><div class="row between wrap"><div><b class="serif" style="font-size:17px">${esc(p.name)}</b> <span class="mono muted small">${p.id}</span></div><span class="b num">${FF.inr(p.price)}</span></div>
        <div class="row wrap gap6">${U.badge('Rack ' + p.rack, 'ink')}${out ? U.badge('Sold out just now', 'bad') : U.badge((sz && sz !== 'FREE' ? 'Size ' + sz + ' · ' : '') + q + ' in stock', q <= 1 ? 'warn' : 'ok')}${pk.sizeKind === 'alterable' ? U.badge('Needs alteration', 'warn') : ''}${pk.sizeKind === 'unstitched' ? U.badge('Unstitched', 'warn') : ''}${pk.offer ? U.badge('Store pick · offer', 'brass') : ''}${pk.held ? U.badge('On hold 30 min', 'info') : ''}${pk.tryon ? U.badge('Tried on phone', 'info') : ''}${stt}</div>
        ${(pk.reasons || []).length ? `<div class="small"><span class="muted">Why it suits:</span> ${FF.pickText(pk).map(esc).join(' · ')}</div>` : ''}${(pk.talk || []).length ? `<div class="small muted">Say: ${pk.talk.map(esc).join(' ')}</div>` : ''}
        ${band !== 'fresh' || push ? `<div class="small warn b">Staff only · Priority: in stock ${FF.ageDays(p)} days${push && push.spiff ? ` · ${FF.inr(push.spiff)} incentive if you sell it` : ''}</div>` : ''}${pk.note ? `<div class="small muted">Staff note: ${esc(pk.note)}</div>` : ''}
        ${open ? `<div class="row wrap gap6 mt4">${out ? `<button class="btn btn-s btn-p" data-act="v-swap" data-code="${v.code}" data-pid="${p.id}">Suggest a swap</button>` : `${pk.state !== 'tried' && pk.state !== 'bag' ? `<button class="btn btn-s" data-act="v-state" data-code="${v.code}" data-pid="${p.id}" data-s="tried">Tried</button>` : ''}<button class="btn btn-s" data-act="v-reject" data-code="${v.code}" data-pid="${p.id}">Rejected…</button>${pk.state === 'bag' ? `<button class="btn btn-s" data-act="v-state" data-code="${v.code}" data-pid="${p.id}" data-s="tried">Remove from bill</button>` : `<button class="btn btn-s btn-p" data-act="v-state" data-code="${v.code}" data-pid="${p.id}" data-s="bag">${FF.icon('plus')} Add to bill</button>`}<button class="btn btn-s btn-g" data-act="v-hold" data-code="${v.code}" data-pid="${p.id}">${pk.held ? 'Release hold' : 'Hold'}</button>`}</div>` : ''}</div></div>`; };
    return `<div class="ph1"><div><a class="link small" href="#/sessions">← Live queue</a><div class="row wrap mt8"><h1 class="code">${v.code}</h1>${U.status(v.status)}${U.badge(FF.cap(v.channel.toLowerCase()))}</div><p>${FF.fmtDT(v.at)}${v.staff ? ' · with ' + esc(FF.staffName(v.staff)) : ''}${v.hist ? ' · ' + U.demo('seeded history') : ''}</p></div>
      <div class="row wrap">${v.status === 'WAITING' ? `<button class="btn btn-p" data-act="v-claim" data-code="${v.code}">Claim</button>` : ''}${open && v.status !== 'WAITING' ? `<button class="btn" data-act="v-nobuy" data-code="${v.code}">No purchase…</button><a class="btn" href="#/billing/${v.code}">${FF.icon('bill')} Bill at counter</a><button class="btn btn-p" data-act="v-sale" data-code="${v.code}">Record sale${inBag.length ? ' · ' + inBag.length : ''}</button>` : ''}<button class="btn btn-g" data-act="pop" data-menu="visit" data-code="${v.code}" aria-label="More">${FF.icon('more')}</button></div></div>
      ${sale ? `<div class="note n-ok mb16">Sale <b class="mono">${sale.no}</b> · ${FF.inr(sale.total)} · ${sale.lines.filter((l) => l.rec).length} of ${sale.lines.length} items were recommended. <a class="link" href="#/sales/${sale.id}">Open bill</a></div>` : ''}${v.status === 'NO_PURCHASE' ? `<div class="note n-plain mb16">Closed without a purchase${v.noBuy ? ' — ' + esc(v.noBuy) : ''}.</div>` : ''}
      <div class="split"><div class="card"><div class="row between wrap"><h2>Picks to bring</h2>${open ? `<button class="btn btn-s" data-act="v-add" data-code="${v.code}">${FF.icon('plus')} Add another piece</button>` : ''}</div>${v.profiles.length > 1 ? `<div class="row wrap mt12">${v.profiles.map((p, i) => `<button class="chip" data-act="v-tab" data-v="${i}" aria-pressed="${i === VS.tab}">${esc(p.label)}</button>`).join('')}</div>` : ''}<div class="mt8">${picks.map(pick).join('') || U.empty('hanger', 'No suitable pieces were found', 'This became a demand gap for the owner. Help the shopper directly and add any piece you bring.')}</div></div>
      <div class="col gap16"><div class="card"><h3>Shopper${v.profiles.length > 1 ? ' · ' + esc(pr.label) : ''}</h3><dl class="kv mt12"><dt>Looking for</dt><dd>${esc(sumry(pr))}</dd><dt>Size</dt><dd>${esc(Object.values(pr.sizes || {}).filter(Boolean).join(', ') || 'Not given')}${pr.height ? ' · ' + FF.cap(pr.height) : ''}</dd><dt>Colours</dt><dd>${(pr.likes || []).length ? 'Likes ' + pr.likes.join(', ') : 'No strong likes'}${(pr.dislikes || []).length ? ' · avoids ' + pr.dislikes.join(', ') : ''}</dd>${pr.isMinor ? `<dt>Age group</dt><dd>Under 18 — parent answered; no tone, camera or try-on</dd>` : `<dt>Tone</dt><dd>${esc(FF.toneLabel(pr))}${pr.method ? ` <span class="muted small">(${esc(pr.method)})</span>` : ''}</dd><dt>Fit goals</dt><dd>${(pr.goals || []).map((g) => FF.TAX.goals[g]).join(', ') || 'None given'}</dd>`}<dt>Language</dt><dd>${{ en: 'English', hi: 'Hindi', gu: 'Gujarati' }[v.lang] || 'English'}</dd><dt>Try-ons</dt><dd>${v.tryons || 0} of ${v.tryLimit || 3} used</dd>${v.rating ? `<dt>Rating</dt><dd>${'★'.repeat(v.rating)}${'☆'.repeat(5 - v.rating)}</dd>` : ''}</dl></div>
      <div class="card"><h3>Timeline</h3><ul class="tl mt12">${(v.events || []).slice().reverse().map((e) => `<li>${esc(e.text)}<div class="tiny muted">${FF.fmtTime(e.at)}${e.by ? ' · ' + esc(e.by) : ''}</div></li>`).join('') || '<li class="muted">No events recorded</li>'}</ul></div></div></div>`; } });
  FF.menu('visit', (d) => { const v = V(d.code), open = ['ASSIGNED', 'TRYING'].includes(v.status); return `${open ? `<button data-act="v-release" data-code="${v.code}">${FF.icon('undo')} Release back to queue</button>` : ''}<button data-act="v-more-try" data-code="${v.code}">${FF.icon('spark')} Allow 3 more try-ons</button><button data-act="v-phone" data-code="${v.code}">${FF.icon('phone')} Open shopper's lookbook</button><button data-act="v-print" data-code="${v.code}">${FF.icon('print')} Print pick list</button><button data-act="v-erase" data-code="${v.code}">${FF.icon('trash')} Erase shopper data…</button>`; });
  FF.act('v-tab', (d) => { VS.tab = +d.v; FF.render(); });
  FF.act('v-state', (d) => { const v = V(d.code), pk = v.picks.find((x) => x.pid === d.pid); pk.state = d.s; if (v.status === 'ASSIGNED') v.status = 'TRYING'; ev(v, d.s, (d.s === 'bag' ? 'Added to bill: ' : 'Tried: ') + FF.prod(d.pid).name); FF.save(); FF.render(); });
  FF.act('v-reject', (d) => FF.modal({ title: 'Why was it rejected?', sub: esc(FF.prod(d.pid).name), size: 'narrow', body: `<p class="small muted mb8">One tap. These reasons tune the rules and show the owner why pieces do not sell.</p><div class="col gap6">${FF.TAX.rejectReasons.map((r) => `<button class="btn" style="justify-content:flex-start" data-act="v-reject-save" data-code="${d.code}" data-pid="${d.pid}" data-r="${esc(r)}">${esc(r)}</button>`).join('')}</div>` }));
  FF.act('v-reject-save', (d) => { const v = V(d.code), pk = v.picks.find((x) => x.pid === d.pid); pk.state = 'rejected'; pk.reason = d.r; if (v.status === 'ASSIGNED') v.status = 'TRYING'; ev(v, 'rejected', `Rejected: ${FF.prod(d.pid).name} — ${d.r}`); FF.save(); FF.closeOverlay(); FF.render(); });
  FF.act('v-hold', (d) => { const v = V(d.code), pk = v.picks.find((x) => x.pid === d.pid); pk.held = !pk.held; ev(v, 'hold', (pk.held ? 'Held for 30 min: ' : 'Hold released: ') + FF.prod(d.pid).name); FF.save(); FF.render(); FF.toast(pk.held ? 'Reserved for 30 minutes' : 'Hold released', 'ok'); });
  FF.act('v-swap', (d) => { const v = V(d.code), old = FF.prod(d.pid), res = FF.engine.recommend(v.profiles[0], { holdout: v.holdout }), alt = res.all.find((i) => !v.picks.some((p) => p.pid === i.pid)) || res.all.find((i) => i.pid !== d.pid); if (!alt) return FF.toast('No similar piece in stock', 'warn'); const pk = v.picks.find((x) => x.pid === d.pid); Object.assign(pk, { pid: alt.pid, size: alt.m.size, sizeKind: alt.m.kind, reasons: alt.reasons.slice(0, 2).map((x) => ({ k: x.k, v: x.v })), offer: alt.offer, talk: FF.engine.talk(alt), state: 'shown', note: 'Swapped for ' + old.name + ' (sold out)' }); ev(v, 'swap', `${old.name} sold out → suggested ${alt.p.name}`); FF.save(); FF.render(); FF.toast('Swapped for ' + alt.p.name, 'ok'); });
  FF.act('v-release', (d) => { const v = V(d.code); v.status = 'WAITING'; v.staff = null; v.waitingSince = Date.now(); ev(v, 'release', 'Released back to queue'); FF.save(); $('.pop')?.remove(); FF.go('#/sessions'); });
  FF.act('v-more-try', (d) => { const v = V(d.code); v.tryLimit = (v.tryLimit || 3) + 3; ev(v, 'tryon', 'Try-on limit raised to ' + v.tryLimit); FF.save(); $('.pop')?.remove(); FF.render(); FF.toast('Shopper can make 3 more previews', 'ok'); });
  FF.act('v-phone', (d) => { $('.pop')?.remove(); window.open('phone.html?code=' + d.code, '_blank'); });
  FF.act('v-print', (d) => { $('.pop')?.remove(); const v = V(d.code); FF.modal({ title: 'Pick list · ' + v.code, body: `<div class="receipt printable"><div class="center"><b>PICK LIST ${v.code}</b><br>${FF.fmtDT(Date.now())}</div><hr>${v.picks.map((pk) => { const p = FF.prod(pk.pid); return `<div class="rr"><span>${v.shortlist.includes(pk.pid) ? '★ ' : ''}${esc(p.name)}<br>&nbsp;${p.id} · ${pk.size || ''}</span><span><b>${p.rack}</b></span></div>`; }).join('')}<hr><div class="center">★ = shopper asked to try</div></div>`, footer: `<button class="btn btn-p" data-act="print">${FF.icon('print')} Print</button>` }); });
  FF.act('print', () => window.print());
  FF.act('v-erase', (d) => { $('.pop')?.remove(); FF.confirm('Erase this shopper\'s data?', `Removes the answers, picks and try-ons for ${d.code}. Use this when a shopper asks at the counter. Bills are kept as the law requires. This is logged.`, 'Erase', () => { const v = V(d.code); Object.assign(v, { erased: true, erasedAt: Date.now(), profiles: [], picks: [], shortlist: [], events: [] }); FF.db.erasures.unshift({ at: Date.now(), code: v.code, by: FF.me().name + ' (counter request)', scope: 'Visit profile, picks, try-ons' }); FF.audit('Erased shopper data', v.code, 'Counter request'); FF.save(); FF.render(); FF.toast('Data erased', 'ok'); }, true); });
  /* "Mark as no purchase" keeps the real console's radio list with a one-line description per reason */
  const NOBUY = [['Just browsing', 'Exploring the store, no intent to buy today'], ['Price', 'Liked a piece but the price was too high'], ['Nothing in size', 'Would have bought, but their size was not in stock'], ['Will come back with family', 'Said they will return to decide'], ['Bought elsewhere / will compare', 'Comparing with another shop'], ['Did not like the picks', 'None of the pieces suited their taste']];
  FF.act('v-nobuy', (d) => FF.modal({ title: 'Mark as no purchase', sub: `<span class="code">${d.code}</span> · helps the owner see why shoppers leave`, body: `<form id="nbf" data-submit="v-nobuy-save" class="col gap6"><input type="hidden" name="code" value="${d.code}">${NOBUY.map(([r, ds], i) => `<label class="check card" style="padding:12px 14px;cursor:pointer"><input type="radio" name="r" value="${esc(r)}" required ${i ? '' : 'data-msg="Choose a reason"'}><span><b class="inkc">${esc(r)}</b><br><span class="tiny muted">${esc(ds)}</span></span></label>`).join('')}</form>`, footer: `<button class="btn" data-act="close">Cancel</button><button class="btn btn-d" form="nbf">Mark no purchase</button>` }));
  FF.act('v-nobuy-save', (f) => { const v = V(f.code); v.status = 'NO_PURCHASE'; v.noBuy = f.r; ev(v, 'closed', 'No purchase — ' + f.r); FF.save(); FF.closeOverlay(); FF.render(); FF.toast('Saved — visible on every device', 'ok'); });
  /* add a piece the engine did not pick (override with a reason = feedback) */
  FF.act('v-add', (d) => { FF._addFor = d.code; FF.modal({ title: 'Add another piece', sub: 'Your judgement counts. Tell us why, so the rules can learn.', body: `<input type="search" placeholder="Search name or style code" data-change="v-add-q" aria-label="Search catalogue"><div id="v-add-list" class="mt12"></div>` }); addList(''); });
  const addList = (q) => { const v = V(FF._addFor), list = FF.db.products.filter((p) => p.status === 'LIVE' && FF.stockTotal(p) > 0 && !v.picks.some((x) => x.pid === p.id) && (p.name + p.id).toLowerCase().includes(q.toLowerCase())).slice(0, 6); const el = $('#v-add-list'); if (el) el.innerHTML = list.map((p) => `<div class="row" style="padding:8px 0;border-bottom:1px solid var(--line)"><div class="thumb">${FF.garment(p)}</div><div class="grow"><b>${esc(p.name)}</b><div class="small muted">${p.id} · Rack ${p.rack} · ${FF.inr(p.price)}</div></div><button class="btn btn-s" data-act="v-add-pick" data-pid="${p.id}">Add</button></div>`).join('') || `<p class="muted small">Nothing in stock matches.</p>`; };
  FF.onChange('v-add-q', (q) => addList(q));
  FF.act('v-add-pick', (d) => { FF.closeOverlay(); FF.modal({ title: 'Why this piece?', size: 'narrow', body: `<div class="col gap6">${['Shopper asked for it', 'I think it suits them better', 'Matches something they liked', 'Better price for them'].map((r) => `<button class="btn" style="justify-content:flex-start" data-act="v-add-save" data-pid="${d.pid}" data-r="${r}">${r}</button>`).join('')}</div>` }); });
  FF.act('v-add-save', (d) => { const v = V(FF._addFor), p = FF.prod(d.pid), sz = Object.keys(p.stock).find((s) => p.stock[s] > 0); v.picks.push({ pid: p.id, rank: 99, profile: VS.tab, state: 'added', size: sz, sizeKind: 'staff', reasons: [], note: d.r }); ev(v, 'override', `Staff added ${p.name} — ${d.r}`); FF.save(); FF.closeOverlay(); FF.render(); FF.toast('Added', 'ok'); });

  /* ---------- staff-app sale (works with any billing software: POS level L0) ---------- */
  let SL = null;
  const saleBody = () => { const tt = FF.totals(SL.lines); return `<p class="small muted mb8">For shops that bill in their own software: record what was sold so FitFirst knows the outcome. Stock goes down by size.</p>${SL.lines.map((l, i) => { const p = FF.prod(l.pid); return `<div class="cline"><div class="thumb">${FF.garment(p)}</div><div><b>${esc(l.name)}</b><div class="row wrap gap6 mt4"><select data-change="sl-size" data-i="${i}" style="width:auto;min-height:30px;padding:2px 6px" aria-label="Size">${Object.entries(p.stock).map(([s, q]) => `<option value="${s}" ${s === l.size ? 'selected' : ''} ${q <= 0 ? 'disabled' : ''}>${s} (${q})</option>`).join('')}</select><span class="small muted">Sold at ₹</span><input type="number" data-change="sl-price" data-lazy data-i="${i}" value="${l.price - l.disc}" min="1" max="${l.mrp}" style="width:96px;min-height:30px;padding:2px 6px" aria-label="Price sold at"></div>${l.rec ? '<span class="badge b-ok mt4">Recommended</span>' : '<span class="badge mt4">Other item</span>'}</div><button class="x" data-act="sl-del" data-i="${i}" aria-label="Remove">${FF.icon('trash')}</button></div>`; }).join('') || `<p class="muted">No items yet.</p>`}<button class="btn btn-s mt12" data-act="sl-other">${FF.icon('plus')} Add an item that was not recommended</button><div id="sl-search"></div>
    <div class="grid g2 mt16">${U.field('Their bill number (optional)', `<input id="sl-ref" value="${esc(SL.ref)}" placeholder="e.g. TLY-4412">`, 'Lets the nightly import match this sale instead of counting it twice')}${U.field('Paid by', `<select id="sl-mode">${['UPI', 'CASH', 'CARD'].map((m) => `<option>${m}</option>`).join('')}</select>`)}</div><div class="row between mt16"><span class="muted">Total</span><b class="serif" style="font-size:24px">${FF.inr(tt.total)}</b></div>`; };
  FF.act('v-sale', (d) => { const v = V(d.code), src = v.picks.filter((p) => p.state === 'bag'); SL = { code: v.code, ref: '', lines: src.map((pk) => { const p = FF.prod(pk.pid); return { pid: p.id, name: p.name, size: pk.size && p.stock[pk.size] > 0 ? pk.size : Object.keys(p.stock).find((s) => p.stock[s] > 0), qty: 1, price: p.price, mrp: p.mrp, disc: 0, rec: pk.state !== 'added' }; }) }; FF.modal({ title: 'Record sale · ' + v.code, body: saleBody(), footer: `<button class="btn" data-act="close">Cancel</button><button class="btn btn-p" data-act="sl-save">Save sale</button>` }); });
  const reSale = () => FF.reOverlay({ body: saleBody() });
  FF.onChange('sl-size', (val, el) => { SL.lines[el.dataset.i].size = val; });
  FF.onChange('sl-price', (val, el) => { const l = SL.lines[el.dataset.i], n = Number(val); if (!(n > 0)) { FF.toast('Enter the price it sold for', 'bad'); return reSale(); } if (n > l.mrp) { FF.toast('Cannot sell above MRP ' + FF.inr(l.mrp), 'bad'); return reSale(); } l.disc = Math.max(0, l.price - n); if (n > l.price) { l.price = n; l.disc = 0; } reSale(); });
  FF.act('sl-del', (d) => { SL.lines.splice(d.i, 1); reSale(); });
  FF.act('sl-other', () => { $('#sl-search').innerHTML = `<input class="mt8" type="search" placeholder="Search the catalogue" data-change="sl-q" aria-label="Search"><div id="sl-res"></div>`; $('#sl-search input').focus(); });
  FF.onChange('sl-q', (q) => { $('#sl-res').innerHTML = q.length < 2 ? '' : FF.db.products.filter((p) => p.status === 'LIVE' && FF.stockTotal(p) > 0 && (p.name + p.id).toLowerCase().includes(q.toLowerCase())).slice(0, 5).map((p) => `<button class="btn btn-g btn-block" style="justify-content:flex-start" data-act="sl-add" data-pid="${p.id}">${esc(p.name)} · ${p.id} · ${FF.inr(p.price)}</button>`).join('') || '<p class="small muted mt8">No match.</p>'; });
  FF.act('sl-add', (d) => { const p = FF.prod(d.pid); SL.lines.push({ pid: p.id, name: p.name, size: Object.keys(p.stock).find((s) => p.stock[s] > 0), qty: 1, price: p.price, mrp: p.mrp, disc: 0, rec: false }); reSale(); });
  FF.act('sl-save', (d, el) => { if (!SL.lines.length) return FF.toast('Add at least one item', 'bad'); el.disabled = true; const tt = FF.totals(SL.lines), r = FF.recordSale({ source: 'STAFF_APP', visit: SL.code, lines: SL.lines, pay: [{ mode: $('#sl-mode').value, amt: tt.total, ref: $('#sl-ref').value }], doc: 'RECEIPT', attribution: 'STAFF_LINKED' }); if (r.error) { el.disabled = false; return FF.toast(r.error, 'bad'); } FF.closeOverlay(); FF.render(); FF.toast('Sale saved · ' + FF.inr(tt.total), 'ok'); });

  /* ---------- history ---------- */
  /* the V1 visit-history page is merged into V2's Sessions page */
})();
